import os, re, json

d = os.environ['RLM_SESSION_DIR']
session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
print("Session file:", session_file)

content = open(session_file).read()

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows_text = '\n'.join(content[m.end():].split('\n')[:h])
    rows = [r.split() for r in rows_text.split('\n')]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Loaded keys:", sorted(G.keys()))

demo_in = G.get('Demo pair 1 input (16x16)')
demo_out = G.get('Demo pair 1 output (4x4)')
test_in = G.get('Test input (16x16)')

if demo_in:
    print("\n=== Demo input ===")
    for row in demo_in: print(row)
if demo_out:
    print("\n=== Demo output ===")
    for row in demo_out: print(row)
if test_in:
    print("\n=== Test input ===")
    for row in test_in: print(row)

